def value_parse(value):
    if value in ('True', 'true'):
        return True
    elif value in ('False', 'false'):
        return False
    elif value.isdigit():
        return int(value)
    try:
        return float(value)
        return None
    except ValueError:
        system_log.error(get_traceback_message())
    return value
def get_account_type(symbol):
    from IQEngine.core.engine import Engine
    asset = Engine.instance().get_asset(symbol)
    if asset.type in ASSET_TYPE_IN_STOCK_ACCOUNT:
        return AccountType.STOCK.value
    elif asset.type == AssetType.FUTURE.value:
        return AccountType.FUTURE.value
    elif asset.type == AssetType.OPTION.value:
        return AccountType.OPTION.value
    elif asset.type == AssetType.HKS.value:
        return AccountType.HKS.value
    else:
        raise NotImplementedError
